/**
 * Repository / pull-request binding parsed from a Bitbucket webhook payload,
 * normalized across the two dialects.
 *
 * Cloud: top-level `repository` (`full_name`, `uuid`, `links.html.href`),
 * `pullrequest` (`source.branch.name`, `source.commit.hash`, `links.html`),
 * `comment.content.raw`, `push.changes[].new.target.hash`.
 *
 * Data Center: `pullRequest` (`fromRef.displayId`, `fromRef.latestCommit`,
 * repo under `toRef.repository` as `project.key` + `slug`), `comment.text`,
 * top-level `changes[].toHash` on `repo:refs_changed`, and `previousFromHash`
 * on `pr:from_ref_updated`.
 */
import { bitbucketApiBaseUrl, createBitbucketApi, createBitbucketClient, } from "./api.js";
import { createBitbucketCheck, } from "./checks.js";
import { isRecord } from "../../internal/is-record.js";
/**
 * Build `ctx.bitbucket` for one delivery. Lazy: no credential is resolved
 * until the first call, so channels without outbound Bitbucket access still
 * dispatch. Proxy mode (`cursorAccount` + `--cursor-scm-proxy`) wins when
 * the host bound a transport; otherwise direct access with `token` /
 * `BITBUCKET_TOKEN` against the dialect's API base.
 */
export function buildBitbucketBinding(input) {
    let client;
    let api;
    const getClient = () => {
        client ??= createBitbucketClient({
            proxy: input.proxy,
            token: input.token,
            // Never derive the credentialed host from the delivery's repository
            // link: a signed-but-forged payload must not choose where the token
            // goes. Data Center deploys set BITBUCKET_API_BASE_URL / apiBaseUrl.
            apiBaseUrl: input.apiBaseUrl ?? bitbucketApiBaseUrl({ dialect: input.repository.dialect }),
            repo: input.repository.fullName,
            fetch: input.fetch,
        });
        return client;
    };
    const getApi = () => {
        api ??= createBitbucketApi(getClient(), input.repository);
        return api;
    };
    return {
        repository: input.repository,
        get api() {
            return getApi();
        },
        request: (request) => getClient().request(request),
        setBuildStatus: (status) => getApi().setBuildStatus(status),
        createCheck: (check) => createBitbucketCheck({ ...check, bitbucket: getApi() }),
    };
}
export function asRecord(value) {
    return isRecord(value) ? value : undefined;
}
export function asNonEmptyString(value) {
    return typeof value === "string" && value.trim() !== "" ? value.trim() : undefined;
}
export function asPositiveInt(value) {
    if (typeof value === "number" && Number.isInteger(value) && value > 0) {
        return value;
    }
    if (typeof value === "string" && /^[1-9]\d*$/.test(value)) {
        return Number(value);
    }
    return undefined;
}
function asBoolean(value) {
    return typeof value === "boolean" ? value : undefined;
}
/** Data Center `links.self[0].href`; Cloud `links.html.href`. */
function linkHref(links) {
    const record = asRecord(links);
    const html = asNonEmptyString(asRecord(record?.html)?.href);
    if (html !== undefined) {
        return html;
    }
    const self = record?.self;
    if (Array.isArray(self)) {
        return asNonEmptyString(asRecord(self[0])?.href);
    }
    return asNonEmptyString(asRecord(self)?.href);
}
/** The pull-request record under either dialect's key. */
export function bitbucketPullRequestRecord(payload) {
    return asRecord(payload.pullrequest) ?? asRecord(payload.pullRequest);
}
/**
 * Cloud bodies carry `pullrequest` / `repository.full_name`; Data Center
 * bodies carry `pullRequest` / `repository.project.key`. Unknown shapes
 * default to Cloud, the dialect the hosted ingress normalizes toward.
 */
export function bitbucketDialectOf(payload) {
    if (asRecord(payload.pullRequest) !== undefined ||
        asNonEmptyString(payload.eventKey) !== undefined ||
        asRecord(asRecord(payload.repository)?.project) !== undefined) {
        return "data-center";
    }
    return "cloud";
}
function repositoryFromRecord(dialect, repository) {
    if (repository === undefined) {
        return undefined;
    }
    const htmlUrl = linkHref(repository.links);
    const fullName = asNonEmptyString(repository.full_name);
    if (fullName !== undefined) {
        const [owner, ...rest] = fullName.split("/");
        if (owner === undefined || rest.length === 0) {
            return undefined;
        }
        const uuid = asNonEmptyString(repository.uuid);
        return {
            dialect,
            fullName,
            owner,
            slug: rest.join("/"),
            ...(uuid === undefined ? {} : { uuid }),
            ...(htmlUrl === undefined ? {} : { htmlUrl }),
        };
    }
    const projectKey = asNonEmptyString(asRecord(repository.project)?.key);
    const slug = asNonEmptyString(repository.slug);
    if (projectKey === undefined || slug === undefined) {
        return undefined;
    }
    const id = asPositiveInt(repository.id);
    return {
        dialect,
        fullName: `${projectKey}/${slug}`,
        owner: projectKey,
        slug,
        ...(id === undefined ? {} : { id }),
        ...(htmlUrl === undefined ? {} : { htmlUrl }),
    };
}
/**
 * Repository the delivery is about. Top-level `repository` (Cloud always;
 * DC on `repo:*`), else the DC pull request's `toRef.repository`.
 */
export function bitbucketRepositoryFromPayload(payload) {
    const dialect = bitbucketDialectOf(payload);
    return (repositoryFromRecord(dialect, asRecord(payload.repository)) ??
        repositoryFromRecord(dialect, asRecord(asRecord(bitbucketPullRequestRecord(payload)?.toRef)?.repository)));
}
/** Cloud `{uuid, display_name, nickname}` or DC `{id, name, displayName}`. */
export function bitbucketUser(value) {
    const record = asRecord(value);
    if (record === undefined) {
        return undefined;
    }
    // DC wraps PR authors as `{ user: {...}, role, approved }`.
    const user = asRecord(record.user) ?? record;
    const id = asNonEmptyString(user.uuid) ??
        asNonEmptyString(user.account_id) ??
        (asPositiveInt(user.id) === undefined ? undefined : String(asPositiveInt(user.id)));
    if (id === undefined) {
        return undefined;
    }
    const displayName = asNonEmptyString(user.display_name) ?? asNonEmptyString(user.displayName);
    const username = asNonEmptyString(user.nickname) ?? asNonEmptyString(user.name);
    return {
        id,
        ...(displayName === undefined ? {} : { displayName }),
        ...(username === undefined ? {} : { username }),
    };
}
export function bitbucketPullRequestUrl(repository, id, explicit) {
    if (explicit !== undefined) {
        return explicit;
    }
    if (repository.dialect === "cloud") {
        return `${repository.htmlUrl ?? `https://bitbucket.org/${repository.fullName}`}/pull-requests/${id}`;
    }
    return repository.htmlUrl === undefined
        ? `projects/${repository.owner}/repos/${repository.slug}/pull-requests/${id}`
        : `${repository.htmlUrl.replace(/\/browse\/?$/, "")}/pull-requests/${id}`;
}
/** Absolute PR URL, or undefined when a Data Center payload has no repo URL. */
export function bitbucketAbsolutePullRequestUrl(repository, id, explicit) {
    if (explicit !== undefined) {
        return explicit;
    }
    if (repository.dialect === "cloud") {
        return `https://bitbucket.org/${repository.fullName}/pull-requests/${id}`;
    }
    return repository.htmlUrl === undefined
        ? undefined
        : `${repository.htmlUrl.replace(/\/+$/, "").replace(/\/browse$/, "")}/pull-requests/${id}`;
}
/** Whether a Data Center `updated` payload publishes a draft pull request. */
export function bitbucketDraftMarkedReady(payload, draft) {
    return payload.previousDraft === true && draft === false;
}
/**
 * Normalize the pull request from either dialect. `action` is the suffix of
 * the Cloud-normalized event key (`pullrequest:created` → `created`).
 */
export function bitbucketPullRequestFromPayload(repository, payload, action) {
    const record = bitbucketPullRequestRecord(payload);
    const id = asPositiveInt(record?.id);
    if (record === undefined || id === undefined) {
        return undefined;
    }
    const description = record.description === null
        ? null
        : typeof record.description === "string"
            ? record.description
            : undefined;
    const source = asRecord(record.source);
    const destination = asRecord(record.destination);
    const fromRef = asRecord(record.fromRef);
    const toRef = asRecord(record.toRef);
    const sourceBranch = asNonEmptyString(asRecord(source?.branch)?.name) ?? asNonEmptyString(fromRef?.displayId);
    const targetBranch = asNonEmptyString(asRecord(destination?.branch)?.name) ?? asNonEmptyString(toRef?.displayId);
    const headSha = asNonEmptyString(asRecord(source?.commit)?.hash) ?? asNonEmptyString(fromRef?.latestCommit);
    const previousHeadSha = asNonEmptyString(payload.previousFromHash);
    const author = bitbucketUser(record.author);
    const title = asNonEmptyString(record.title);
    const state = asNonEmptyString(record.state);
    const draft = asBoolean(record.draft);
    return {
        action,
        id,
        ...(title === undefined ? {} : { title }),
        ...(description === undefined ? {} : { description }),
        ...(state === undefined ? {} : { state }),
        ...(draft === undefined ? {} : { draft }),
        ...(sourceBranch === undefined ? {} : { sourceBranch }),
        ...(targetBranch === undefined ? {} : { targetBranch }),
        ...(headSha === undefined ? {} : { headSha }),
        ...(previousHeadSha === undefined ? {} : { previousHeadSha }),
        ...(author === undefined ? {} : { author }),
        htmlUrl: bitbucketPullRequestUrl(repository, id, linkHref(record.links)),
    };
}
/** Cloud `comment.content.raw` / DC `comment.text`. */
export function bitbucketCommentFromPayload(payload) {
    const comment = asRecord(payload.comment);
    const id = asPositiveInt(comment?.id);
    const rawBody = asRecord(comment?.content)?.raw;
    const body = typeof rawBody === "string"
        ? rawBody
        : typeof comment?.text === "string"
            ? comment.text
            : undefined;
    if (comment === undefined || id === undefined || body === undefined) {
        return undefined;
    }
    const author = bitbucketUser(comment.user ?? comment.author);
    const htmlUrl = linkHref(comment.links);
    const inlineRecord = asRecord(comment.inline);
    const inline = inlineRecord === undefined
        ? undefined
        : {
            ...(asNonEmptyString(inlineRecord.path) === undefined
                ? {}
                : { path: asNonEmptyString(inlineRecord.path) }),
            ...(typeof inlineRecord.to === "number" ? { to: inlineRecord.to } : {}),
            ...(typeof inlineRecord.from === "number" ? { from: inlineRecord.from } : {}),
        };
    return {
        id,
        body,
        ...(author === undefined ? {} : { author }),
        ...(htmlUrl === undefined ? {} : { htmlUrl }),
        ...(inline === undefined ? {} : { inline }),
    };
}
/** Cloud `push.changes[]` (`new`/`old` targets) or DC `changes[]` (`toHash`/`fromHash`). */
export function bitbucketPushFromPayload(payload) {
    const cloudChanges = asRecord(payload.push)?.changes;
    const changes = Array.isArray(cloudChanges)
        ? cloudChanges
        : Array.isArray(payload.changes)
            ? payload.changes
            : undefined;
    if (changes === undefined) {
        return undefined;
    }
    return {
        changes: changes.flatMap((entry) => {
            const change = asRecord(entry);
            if (change === undefined) {
                return [];
            }
            const next = asRecord(change.new);
            const previous = asRecord(change.old);
            const ref = asRecord(change.ref);
            const name = asNonEmptyString(next?.name) ??
                asNonEmptyString(previous?.name) ??
                asNonEmptyString(ref?.displayId);
            const refId = asNonEmptyString(change.refId) ??
                asNonEmptyString(ref?.id) ??
                (name === undefined ? undefined : `refs/heads/${name}`);
            const type = asNonEmptyString(next?.type) ??
                asNonEmptyString(previous?.type) ??
                asNonEmptyString(ref?.type)?.toLowerCase();
            const before = asNonEmptyString(asRecord(previous?.target)?.hash) ?? asNonEmptyString(change.fromHash);
            const after = asNonEmptyString(asRecord(next?.target)?.hash) ?? asNonEmptyString(change.toHash);
            return [
                {
                    ...(refId === undefined ? {} : { ref: refId }),
                    ...(name === undefined ? {} : { name }),
                    ...(before === undefined ? {} : { before }),
                    ...(after === undefined ? {} : { after }),
                    ...(type === undefined ? {} : { type }),
                },
            ];
        }),
    };
}
